class PingWindow {
  private times: number[] = [];

  ping(t: number): number {
    this.times.push(t);
    let lo = 0, hi = this.times.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.times[mid] >= t - 3000) hi = mid;
      else lo = mid + 1;
    }
    return this.times.length - lo;
  }
}

